const input = $input.first().json;
const git = input.git || {};
const n8n = input.n8n || {};
const portalText = (input.portal_status_text || '').trim();

let context = '=== GIT ACTIVITY (last 7 days) ===\n';
if (git.github_ok === false) {
  context += `COULD NOT FETCH GITHUB DATA. Error: ${git.error}\n`;
} else if (!git.total_commits) {
  context += 'No commits in any repo this week.\n';
} else {
  for (const r of (git.repos || [])) {
    if (!r.commit_count) continue;
    context += `Repo: ${r.name} (${r.commit_count} commits)\n`;
    for (const c of r.commits) context += `  - ${c.message} (${c.sha})\n`;
  }
}

context += '\n=== N8N AUTOMATION RUNS (last 7 days) ===\n';
if (n8n.n8n_ok === false) {
  context += `COULD NOT FETCH N8N EXECUTION DATA. Error: ${n8n.error}\n`;
} else if (!n8n.total_executions) {
  context += 'No workflow executions this week.\n';
} else {
  for (const [name, counts] of Object.entries(n8n.by_workflow || {})) {
    context += `${name}: ${counts.success} succeeded, ${counts.error} failed\n`;
  }
  if ((n8n.failures || []).length) {
    context += 'Failures:\n';
    for (const f of n8n.failures) context += `  - ${f.workflow} (execution ${f.executionId}, ${f.startedAt})\n`;
  }
}

context += '\n=== FLYRANK PORTAL STATUS ===\n';
context += portalText ? portalText : 'NOT PROVIDED THIS RUN.';

return [{ json: { context } }];

const ctx = $('Build Context').first().json.context;
return [{ json: {
  output: { report: "Both Groq and Gemini failed to generate this week's report. Raw data below:\n\n" + ctx },
  ai_provider: 'both_failed',
}}];
